package com.dixitdada.journalApp.service; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.Date; @Service public class JwtService { private final SecretKey key; private final long mins; public JwtService(@Value("${app.jwt.secret}") String s,@Value("${app.jwt.expiration-minutes:1440}") long m){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));mins=m;} public String generate(UserDetails u){Instant n=Instant.now();return Jwts.builder().subject(u.getUsername()).issuedAt(Date.from(n)).expiration(Date.from(n.plus(Duration.ofMinutes(mins)))).signWith(key).compact();} public String username(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload().getSubject();} public boolean valid(String t,UserDetails u){try{return username(t).equals(u.getUsername());}catch(Exception e){return false;}} }